'use strict';
(() => {
const palettes={violet:{shell:'#c6a4f3',shade:'#9369ca',accent:'#7b4bc1',glow:'#e9d6ff'},coral:{shell:'#ffb49a',shade:'#e68065',accent:'#c2634d',glow:'#ffe2cd'},lime:{shell:'#d1e893',shade:'#91b65d',accent:'#678f3d',glow:'#edf9c7'}};
function botSVG(type){const c=palettes[type]||palettes.violet;return `<svg class="anime-bot bot-${type}" viewBox="0 0 180 190" xmlns="http://www.w3.org/2000/svg" fill="none" aria-hidden="true" focusable="false"><ellipse class="bot-shadow" cx="90" cy="178" rx="43" ry="7" fill="#473454" opacity=".12"/><g class="bot-body"><path d="M69 145 66 168Q66 176 79 174L86 156M104 153 108 172Q120 177 123 168L116 144" fill="${c.shade}" stroke="#45354f" stroke-width="3"/><rect x="54" y="109" width="73" height="52" rx="23" fill="${c.shell}" stroke="#45354f" stroke-width="3"/><path d="M59 142Q90 158 122 142" stroke="${c.shade}" stroke-width="8"/><rect x="72" y="120" width="37" height="24" rx="10" fill="#fff7e8" stroke="#45354f" stroke-width="2"/><path d="m90 124-7 10h7l-2 7 10-11h-8l3-6" fill="${c.accent}"/><g class="bot-arm-left"><path d="M56 119Q40 119 35 139Q34 148 43 148Q49 147 54 135" fill="${c.shell}" stroke="#45354f" stroke-width="3"/><path d="m35 137 12 5" stroke="${c.shade}" stroke-width="4"/></g><g class="bot-wave"><path d="M124 121Q143 120 149 101" stroke="#45354f" stroke-width="15" stroke-linecap="round"/><path d="M124 121Q143 120 149 101" stroke="${c.shell}" stroke-width="10" stroke-linecap="round"/><path d="M144 100 140 87M149 97 150 81M154 100 160 89" stroke="#45354f" stroke-width="7" stroke-linecap="round"/><path d="M144 100 140 87M149 97 150 81M154 100 160 89" stroke="${c.shell}" stroke-width="4" stroke-linecap="round"/></g><g class="bot-head"><path d="M90 40V25" stroke="#45354f" stroke-width="3"/><circle class="antenna-light" cx="90" cy="20" r="7" fill="${c.glow}" stroke="#45354f" stroke-width="2.5"/><path d="m38 55-13-9 1 31 15 7M140 55l14-9-1 31-13 7" fill="${c.shade}" stroke="#45354f" stroke-width="3"/><rect x="32" y="38" width="115" height="79" rx="31" fill="${c.shell}" stroke="#45354f" stroke-width="3"/><path d="M48 47Q69 36 104 44" stroke="${c.glow}" stroke-width="5" stroke-linecap="round"/><rect x="43" y="54" width="93" height="51" rx="22" fill="#fffaf1" stroke="#45354f" stroke-width="2.5"/><g class="bot-eyes"><ellipse cx="68" cy="78" rx="9" ry="14" fill="#43324f"/><ellipse cx="111" cy="78" rx="9" ry="14" fill="#43324f"/><ellipse cx="70" cy="83" rx="5" ry="7" fill="${c.accent}"/><ellipse cx="113" cy="83" rx="5" ry="7" fill="${c.accent}"/><ellipse cx="65" cy="72" rx="3.5" ry="5" fill="white"/><ellipse cx="108" cy="72" rx="3.5" ry="5" fill="white"/><circle cx="72" cy="82" r="2" fill="white"/><circle cx="115" cy="82" r="2" fill="white"/></g><path d="M82 91q8 9 16 0" stroke="#45354f" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="54" cy="91" rx="7" ry="3.5" fill="#f6a6ac" opacity=".8"/><ellipse cx="125" cy="91" rx="7" ry="3.5" fill="#f6a6ac" opacity=".8"/><path d="m130 43 4-7 3 7 7 2-7 3-3 7-4-7-7-3z" fill="#fff1b5" stroke="#45354f" stroke-width="1.5"/></g></g></svg>`}
document.querySelectorAll('[data-bot]').forEach(el=>{el.innerHTML=botSVG(el.dataset.bot)});
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');let manualPause=false;
const motionButton=document.querySelector('#motion-toggle');
function updateMotion(){const paused=manualPause||reduce.matches;document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'▶ Motion':'Ⅱ Motion';motionButton.setAttribute('aria-label',paused?'Resume decorative animations':'Pause decorative animations');if(reduce.matches){motionButton.textContent='Reduced motion';motionButton.disabled=true;motionButton.setAttribute('aria-label','Reduced motion follows your device setting')}else motionButton.disabled=false;}
motionButton.addEventListener('click',()=>{manualPause=!manualPause;updateMotion()});reduce.addEventListener('change',updateMotion);updateMotion();
const toggle=document.querySelector('#guide-toggle'),panel=document.querySelector('#guide-panel');
function setGuide(open){panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)document.querySelector('#guide-close').focus();}
toggle.addEventListener('click',()=>setGuide(panel.hidden));document.querySelector('#guide-close').addEventListener('click',()=>{setGuide(false);toggle.focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){setGuide(false);toggle.focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.bot-guide'))setGuide(false)});
function chooseMission(key){const filter=document.querySelector(`[data-filter="${key}"]`);if(filter)filter.click();setGuide(false);document.querySelector('#work').scrollIntoView({behavior:document.body.classList.contains('motion-paused')?'instant':'smooth'});if(filter)filter.focus({preventScroll:true});}
document.querySelectorAll('[data-mission]').forEach(b=>b.addEventListener('click',()=>chooseMission(b.dataset.mission)));document.querySelectorAll('[data-guide-mission]').forEach(b=>b.addEventListener('click',()=>chooseMission(b.dataset.guideMission)));document.querySelector('#guide-contact').addEventListener('click',()=>setGuide(false));
const run=document.querySelector('#run-build');run.addEventListener('click',()=>{const hero=document.querySelector('.hero-bot');hero.classList.remove('celebrate');void hero.offsetWidth;hero.classList.add('celebrate');});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('arrived');observer.unobserve(e.target)}})},{threshold:.12});document.querySelectorAll('.mission-card,.lab-shell,.service-shell,.about-grid').forEach(el=>{el.classList.add('arrival-ready');observer.observe(el)})}
})();
